        if op_rate > 0.7 and n > 20:
            return 'C' if rng.random() < 0.5 else 'D'
        return 'D'
    # Opponent cooperated last round
    # If we defected last round and opponent cooperated, they may be forgiving
    if history[-1][0] == 'D':
        # They cooperated despite our defection - exploit cautiously
        if op_rate > 0.8:
            # Keep exploiting but not too obviously
            return 'D' if rng.random() < 0.3 else 'C'
