def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    # Count recent cooperation and defection
    recent = history[-10:] if n >= 10 else history
    opp_c = sum(1 for me, opp in recent if opp == 'C')
    opp_d = len(recent) - opp_c
    my_c = sum(1 for me, opp in recent if me == 'C')
    my_d = len(recent) - my_c

    # Detect potential defection streaks
    last_opp = history[-1][1]
    last_my = history[-1][0]

    # Check for repeated mutual defection - try to break out
    if n >= 5:
        last5 = history[-5:]
        dd_count = sum(1 for me, opp in last5 if me == 'D' and opp == 'D')
        if dd_count >= 4:
            # Try to re-establish cooperation
            return 'C'

    # Check if opponent has been defecting frequently
    if len(recent) >= 5:
        if opp_d >= len(recent) * 0.6:
            # Opponent is mostly defecting - defect too, but occasionally test
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        if opp_c >= len(recent) * 0.8:
            # Opponent is mostly cooperating - cooperate
            return 'C'

    # Tit-for-tat with forgiveness: if opponent just defected, retaliate
    # but occasionally forgive to break cycles
    if last_opp == 'D':
        if last_my == 'D':
            # We're in mutual defection - try to cooperate sometimes
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            # Opponent defected while we cooperated - retaliate
            return 'D'
    else:
        # Opponent cooperated last round
        if last_my == 'D':
            # We defected and they cooperated - be cooperative now
            return 'C'
        return 'C'

    return 'C'

