            return 'C'
        return 'D'
    # Opponent cooperated last
    if last_my == 'D':
        return 'C'
    # Try to exploit a bit in middle game
    if 20 <= n <= 80 and rng.random() < 0.08 and op_c > 2 * op_d:
        return 'D'
    return 'C'
